function art(p){if(p.type==='transport')return `<div class="browser-mock"><div class="browser-bar"><i></i><i></i><i></i></div><div class="mock-nav"><strong>THUÊ LÁI<span style="color:#91a949">.</span></strong><span>Hành trình của bạn · An tâm mỗi chuyến đi</span></div><div class="mock-content"><div><div class="mock-title">Bạn tận hưởng.<br><em>Chúng tôi cầm lái.</em></div><div class="mock-sub">Kết nối tài xế cho hành trình của bạn.</div><div class="mock-cta">Đặt tài xế →</div></div><div style="align-self:end">${car}</div></div></div>${phone('THUÊ LÁI','An tâm trên<br>mọi hành trình','Điểm đón của bạn')}`;if(p.type==='property')return `<div class="property-art"><div class="building"></div><div class="property-copy"><strong>${p.name}</strong><p>Không gian mới.<br>Khởi đầu mới.</p><div class="property-lines"></div><div class="property-lines"></div><div class="mock-cta">Khám phá →</div></div></div>`;if(p.type==='commerce')return `<div class="commerce-art"><header>${p.name}<span style="float:right;font-size:12px">⌕ &nbsp; ☰</span></header><p style="font-size:10px;margin:10px 0">Khám phá lựa chọn dành cho bạn.</p><div class="product-grid"><div class="product-tile">◒</div><div class="product-tile">▱</div><div class="product-tile">◍</div></div></div>`;if(p.type==='circle')return `${phone('Circle','Gần nhau hơn.<br>An tâm hơn.','Nhóm gia đình')}<div style="width:130px;height:130px;border:1px solid #ae9ac8;border-radius:50%;display:grid;place-items:center;margin-left:20px;font-size:55px;color:#89729e">⌖</div>`;return `<div style="width:57%;margin-right:12px"><p style="font-size:27px;line-height:1.25;font-weight:600;letter-spacing:-1px">${p.type==='island'?'Một hòn đảo.<br>Vạn hành trình.':'Chọn xe.<br>Mở hành trình.'}</p>${car}</div>${phone(p.name,p.type==='island'?'Khám phá<br>Phú Quốc':'Đi theo cách<br>của bạn',p.type==='island'?'Phú Quốc':'Bạn muốn đi đâu?')}`}
