function screenshotPreview(p){const images=projectImages[p.name];return `<div class="real-preview ${p.featured?'real-featured':''} ${images.length>1&&!p.featured?'real-duo':''}">${images.slice(0,2).map(im=>`<div class="screenshot-frame ${im.kind}"><div class="screenshot-bar"><span>● ● ●</span><span>${im.kind==='web'?'WEB EXPERIENCE':'MOBILE EXPERIENCE'}</span></div><img src="${im.src}" alt="${im.alt}" loading="lazy" decoding="async"></div>`).join('')}</div>`}
const container=document.querySelector('#projects');
projects.forEach((p,i)=>{const article=document.createElement('article');article.className='project'+(p.featured?' featured':'');article.dataset.category=p.category;article.innerHTML=`<div class="project-visual" style="--panel:${p.color}"><span class="project-index">${String(i+1).padStart(2,'0')} / ${p.featured?'FEATURED PROJECT':'SELECTED PROJECT'}</span>${projectImages[p.name]?screenshotPreview(p):art(p)}<small>${projectImages[p.name]?'ẢNH GIAO DIỆN ĐÃ CUNG CẤP':'PRODUCT ILLUSTRATION'}</small></div><div class="project-caption"><div><h3>${p.name}</h3><p>${p.label}</p></div><button class="round-button" aria-label="Xem chi tiết ${p.name}">↗</button></div>`;article.querySelector('button').addEventListener('click',()=>openProject(p));container.append(article)});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});let count=0;container.querySelectorAll('.project').forEach(card=>{card.hidden=button.dataset.filter!=='all'&&!card.dataset.category.split(' ').includes(button.dataset.filter);if(!card.hidden)count++});document.querySelector('#filter-status').textContent=`Hiển thị ${count} dự án.`}));
const dialog=document.querySelector('#project-dialog');function openProject(p){document.querySelector('#dialog-content').innerHTML=`<p class="eyebrow">${p.label}</p><h2>${p.name}</h2>${p.role?`<p><strong>${p.role}</strong><br>${p.date}</p>`:''}<p>${p.description}</p>${p.tasks?`<h3>Đóng góp trong dự án</h3><ul>${p.tasks.map(t=>`<li>${t}</li>`).join('')}</ul>`:''}${p.stack?`<div class="tags">${p.stack}</div>`:''}${projectImages[p.name]?`<section class="project-gallery" aria-label="Ảnh giao diện dự án"><h3>Giao diện sản phẩm</h3><p class="gallery-hint">Nhấn ảnh để mở bản đầy đủ trong tab mới.</p>${projectImages[p.name].map(im=>`<figure class="gallery-item ${im.kind}"><a href="${im.src}" target="_blank" rel="noopener noreferrer"><img src="${im.src}" alt="${im.alt}" loading="lazy"></a><figcaption>${im.alt}</figcaption></figure>`).join('')}</section>`:''}<div class="dialog-links">${p.links.map(([name,url])=>`<a class="button dark" href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`).join('')}</div>`;dialog.showModal()};document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('#copy-email').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('tuyennh3008@gmail.com');document.querySelector('#copy-status').textContent='Đã sao chép email. Hẹn gặp bạn trong hộp thư!'}catch{document.querySelector('#copy-status').textContent='Email liên hệ: tuyennh3008@gmail.com'}});document.querySelector('#year').textContent=new Date().getFullYear();
